// Auto-generated full HTML sections from Docs/04_hld.html
export const HLD_HTML = {
  "s1": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F3DB;&#xFE0F;</div>\n      <h2 class=\"section-title\">System Overview &mdash; The Big Picture</h2>\n    </div>\n    <p class=\"section-lead\">PRATYAKSHA is a <strong>hybrid local-cloud system</strong>. The most privacy-sensitive computation &mdash; screen capture, vision inference, and PII de-identification &mdash; is performed entirely inside the Chrome browser using WebGPU-accelerated ONNX models. Only a sanitized, token-substituted representation of the screen is sent to cloud services for high-level reasoning.</p>\n    <div class=\"callout orange\">\n      <div class=\"callout-icon\">&#x1F510;</div>\n      <div class=\"callout-body\"><div class=\"callout-title\">The Core Privacy Contract</div>Raw screenshots, biometric data (faces), and Aadhaar/PAN numbers are <strong>NEVER transmitted</strong> outside the browser extension. The Vault service pseudonymises all PII before anything crosses the local boundary. The cloud sees only tokens like <span class=\"mono\">&#x27E8;FACE_001&#x27E9;</span> and <span class=\"mono\">&#x27E8;AADHAAR_01&#x27E9;</span>.</div>\n    </div>\n        <!-- \u2500\u2500 MERMAID MASTER ARCHITECTURE FLOWCHART \u2500\u2500 -->\n    <div class=\"mermaid-wrapper\" id=\"masterArchitectureWrap\">\n      <div class=\"mermaid-header\">\n        <div class=\"mermaid-title\">\n          <span>\ud83c\udfdb\ufe0f Master Microservices Architecture &amp; Service Relationships</span>\n        </div>\n        <div class=\"mermaid-controls\">\n          <button class=\"mermaid-btn\" id=\"zoomInBtn\" title=\"Zoom In\">\ud83d\udd0d +</button>\n          <button class=\"mermaid-btn\" id=\"zoomOutBtn\" title=\"Zoom Out\">\ud83d\udd0d &minus;</button>\n          <button class=\"mermaid-btn\" id=\"zoomResetBtn\" title=\"Reset View\">&#x23FA; Reset</button>\n        </div>\n      </div>\n\n      <div class=\"mermaid-legend\">\n        <div class=\"legend-item\"><span class=\"legend-dot ld-client\"></span><span>Client Presentation &amp; Runner</span></div>\n        <div class=\"legend-item\"><span class=\"legend-dot ld-shield\"></span><span>WebGPU Vision Privacy Shield</span></div>\n        <div class=\"legend-item\"><span class=\"legend-dot ld-vault\"></span><span>Zero-Knowledge Cryptographic Vault</span></div>\n        <div class=\"legend-item\"><span class=\"legend-dot ld-gateway\"></span><span>Edge Ingress &amp; Auth (DMZ)</span></div>\n        <div class=\"legend-item\"><span class=\"legend-dot ld-cloud\"></span><span>Sovereign Cloud Reasoning (vLLM)</span></div>\n        <div class=\"legend-item\"><span class=\"legend-dot ld-storage\"></span><span>Enterprise Storage &amp; Telemetry</span></div>\n        <div class=\"legend-item\"><span class=\"legend-dot ld-gate\"></span><span>Security &amp; Human Approval Gate</span></div>\n      </div>\n\n      <div class=\"mermaid-box\" id=\"mermaidBoxMain\">\n        <pre class=\"mermaid\" id=\"mermaidPreMain\">\nflowchart TD\n    %% Custom Semantic Styling Classes\n    classDef client fill:#EFF6FF,stroke:#2563EB,stroke-width:2px,color:#1E40AF;\n    classDef shield fill:#FFF7ED,stroke:#EA580C,stroke-width:2px,color:#9A3412;\n    classDef vault fill:#F5F3FF,stroke:#7C3AED,stroke-width:2px,color:#5B21B6;\n    classDef gateway fill:#FEF3C7,stroke:#D97706,stroke-width:2px,color:#92400E;\n    classDef cloud fill:#ECFDF5,stroke:#059669,stroke-width:2px,color:#065F46;\n    classDef storage fill:#F8FAFC,stroke:#475569,stroke-width:2px,color:#1E293B;\n    classDef gate fill:#FFF1F2,stroke:#E11D48,stroke-width:2px,stroke-dasharray: 4 4,color:#9F1239;\n\n    subgraph PHASE1 [\"\ud83d\udd12 STAGE 1: ON-DEVICE PERCEPTION & PRIVACY SHIELD (Client MV3 Sandbox)\"]\n        direction TB\n        User([\"\ud83d\udc64 User / Security Operator\"]):::client\n        SidePanel[\"\ud83d\udda5\ufe0f svc-ext-shell (Chrome Side Panel UI \u00b7 Audit HUD)\"]:::client\n        TargetTab[\"\ud83c\udf10 Target Web Portal (ISRO e-Procurement \u00b7 GeM \u00b7 SAKSHAM)\"]:::client\n        ContentExtractor[\"\ud83d\udcdc Content Script (DOM Scene Tree Extractor & Element Walker)\"]:::client\n        \n        subgraph WEBGPU_PIPELINE [\"\u26a1 svc-vision-local (Dedicated WebGPU Offscreen Context)\"]\n            TileDiff[\"\u26a1 8x8 Dirty-Tile dHash (Temporal Diff Filter \u00b7 Skips >85% Static Frames)\"]:::shield\n            NeuralDet[\"\ud83d\udd0d DBNet-Tiny + Ultra-Light-Face (Neural Text & Biometric Detectors)\"]:::shield\n            IndicOCR[\"\ud83d\udd24 Indic CRNN Engine (Devanagari, Tamil, Hindi, Latin OCR)\"]:::shield\n            PIIRules[\"\ud83c\uddee\ud83c\uddf3 Sovereign PII Validator (Verhoeff Checksum \u00b7 PAN \u00b7 GSTIN)\"]:::shield\n            Inpainter[\"\ud83c\udfa8 Safety Halo Inpainter (4px Dilated Redaction Canvas)\"]:::shield\n        end\n\n        VaultTokenize[(\"\ud83d\udd10 svc-vault-local: Tokenize<br/>(Maps Real PII \u2794 \u27e8SYNTHETIC_TOKENS\u27e9 in AES-256 Vault)\")]:::vault\n        MerkleChain[(\"\ud83d\udcdc Tamper-Proof Audit Chain (SHA-256 Merkle Ledger)\")]:::vault\n    end\n\n    subgraph PHASE2 [\"\ud83d\udeaa STAGE 2: ZERO-TRUST EDGE GATEWAY & EGRESS PERIMETER (DMZ)\"]\n        direction TB\n        EgressGuard{\"\ud83d\udee1\ufe0f Zero-Raw-PII Egress Guard<br/>(Hardware / Heuristic Packet Filter)\"}:::gate\n        APIGateway[\"\ud83d\udeaa svc-gateway<br/>(Envoy Ingress \u00b7 TLS 1.3 mTLS \u00b7 WSS Proxy)\"]:::gateway\n        AuthService[\"\ud83d\udd11 svc-auth<br/>(Device Attestation & Short-Lived JWT)\"]:::gateway\n    end\n\n    subgraph PHASE3 [\"\ud83e\udde0 STAGE 3: SOVEREIGN REASONING TIER (Air-Gapped Intranet)\"]\n        direction TB\n        Orchestrator[\"\ud83e\udde0 svc-orchestrator<br/>(FastAPI \u00b7 LangGraph State Machine Loop)\"]:::cloud\n        SovereignVLM[\"\ud83e\udd16 svc-vlm-cloud<br/>(Qwen2.5-VL-7B \u00b7 vLLM PagedAttention GPU)\"]:::cloud\n        PolicyEngine[\"\ud83d\udcdc svc-policy<br/>(Open Policy Agent \u00b7 Rego Guardrails)\"]:::cloud\n        \n        subgraph PERSISTENCE [\"\ud83d\udcbe Enterprise Telemetry & Persistence\"]\n            PostgresDB[(\"\ud83d\uddc4\ufe0f PostgreSQL (Session State & Trajectories)\")]:::storage\n            RedisCluster[(\"\u26a1 Redis Cluster (Locks & Token Cache)\")]:::storage\n            TimescaleDB[(\"\ud83d\udcca TimescaleDB (High-Throughput Telemetry)\")]:::storage\n            MinIOS3[(\"\ud83d\udce6 MinIO S3 (Sanitized Frames & Audit)\")]:::storage\n        end\n    end\n\n    subgraph PHASE4 [\"\ud83d\udd10 STAGE 4: LOCAL REHYDRATION & SAFE DOM EXECUTION (Service Worker & Tab)\"]\n        direction TB\n        AgentRunner[\"\ud83e\udd16 svc-agent-local<br/>(Action Downlink Receiver & State Machine)\"]:::client\n        HumanApprovalGate{\"\u26a0\ufe0f Level-3 Risk Gate<br/>(Mandatory User Confirmation Modal)\"}:::gate\n        VaultRehydrate[(\"\ud83d\udd10 svc-vault-local: Rehydrate<br/>(Swaps \u27e8TOKEN\u27e9 \u2794 Real PII in Local Volatile RAM)\")]:::vault\n        DOMDispatcher[\"\ud83d\udcdc Content Script (Synthetic Event Dispatcher)\"]:::client\n        MutatedTab[\"\ud83c\udf10 Target Web Portal (Mutated DOM State / Form Filled)\"]:::client\n    end\n\n    %% STAGE 1 FLOW\n    User -->|\"1. Submit Task Intent\"| SidePanel\n    SidePanel -->|\"2. Trigger Capture\"| ContentExtractor\n    ContentExtractor -->|\"3a. DOM Scene Tree\"| Inpainter\n    TargetTab -->|\"3b. Viewport Pixels (captureVisibleTab)\"| TileDiff\n    \n    TileDiff -->|\"4. Changed Tiles\"| NeuralDet\n    NeuralDet -->|\"5. BBoxes (Text & Faces)\"| IndicOCR\n    IndicOCR -->|\"6. Extracted Strings\"| PIIRules\n    PIIRules -->|\"7. Verified Coordinates\"| VaultTokenize\n    \n    VaultTokenize -->|\"8. Synthetic Tokens (\u27e8AADHAAR_01\u27e9)\"| Inpainter\n    Inpainter -->|\"9. Sanitized Canvas + Token Graph\"| MerkleChain\n    MerkleChain -->|\"10. Chained Hash Proof\"| EgressGuard\n\n    %% STAGE 2 FLOW\n    EgressGuard -->|\"11. Verified Zero-PII Egress\"| APIGateway\n    APIGateway <-->|\"12. Validate JWT & Device Attestation\"| AuthService\n    APIGateway -->|\"13. Forward Sanitized Request\"| Orchestrator\n\n    %% STAGE 3 FLOW\n    Orchestrator -->|\"14. Visual Reasoning Prompt (Tokens Only)\"| SovereignVLM\n    SovereignVLM -->|\"15. Candidate Action Hypothesis\"| PolicyEngine\n    PolicyEngine -->|\"16. Validated Action JSON\"| Orchestrator\n    \n    Orchestrator -.->|\"Session State\"| PostgresDB\n    Orchestrator -.->|\"Token Locks\"| RedisCluster\n    Orchestrator -.->|\"Real-Time Metrics\"| TimescaleDB\n    Orchestrator -.->|\"Sanitized Frame Audit\"| MinIOS3\n\n    %% STAGE 4 FLOW (Linear forward transition)\n    Orchestrator ==>|\"17. WSS Action Plan Downlink\"| AgentRunner\n    AgentRunner -->|\"18. Evaluate Action Severity\"| HumanApprovalGate\n    HumanApprovalGate -->|\"L3 Mutation: Prompt User\"| SidePanel\n    SidePanel -->|\"User Approves\"| AgentRunner\n    HumanApprovalGate -->|\"L1/L2 Safe: Auto-Proceed\"| VaultRehydrate\n    \n    AgentRunner -->|\"19. Resolve Token \u27e8AADHAAR_01\u27e9\"| VaultRehydrate\n    VaultRehydrate -->|\"20. Decrypted String (In-Memory Only)\"| AgentRunner\n    AgentRunner -->|\"21. Dispatch Synthetic Event (Click / Type)\"| DOMDispatcher\n    DOMDispatcher -->|\"22. Apply Mutation to Active DOM\"| MutatedTab\n    MutatedTab -.->|\"23. Next Frame Closed-Loop Perception\"| TargetTab\n        </pre>\n        <div class=\"mermaid-canvas-hint\">\n          <span>\ud83d\udd90\ufe0f Drag to Pan</span>\n          <span>\u00b7</span>\n          <span>\ud83d\udd0d Pinch or Scroll to Zoom</span>\n        </div>\n      </div>\n\n      <div class=\"matrix-table-wrap\">\n        <table class=\"api-table\">\n          <thead>\n            <tr>\n              <th>Service Codename</th>\n              <th>Deployment Zone</th>\n              <th>Runtime &amp; Protocol</th>\n              <th>Upstream / Downstream Relationships</th>\n              <th>Security &amp; Data Contract</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td><code>svc-ext-shell</code></td>\n              <td>Chrome MV3 Extension</td>\n              <td>Side Panel UI \u00b7 Chrome Runtime WSS</td>\n              <td>User &rarr; <code>svc-agent-local</code>, <code>Content Script</code></td>\n              <td>Zero network egress authority; user intent input &amp; audit diff UI only.</td>\n            </tr>\n            <tr>\n              <td><code>svc-vision-local</code></td>\n              <td>Offscreen Document</td>\n              <td>WebGPU \u00b7 ONNX Runtime Web</td>\n              <td>Tab Canvas &rarr; <code>svc-vault-local</code>, <code>svc-ledger-local</code></td>\n              <td>Local GPU acceleration; destroys raw pixel buffer immediately after sanitization.</td>\n            </tr>\n            <tr>\n              <td><code>svc-vault-local</code></td>\n              <td>Service Worker</td>\n              <td>IndexedDB (AES-256-GCM)</td>\n              <td><code>svc-vision-local</code> &harr; <code>svc-agent-local</code></td>\n              <td>Single source of truth for PII tokens; keys never leave client device memory.</td>\n            </tr>\n            <tr>\n              <td><code>svc-agent-local</code></td>\n              <td>Service Worker</td>\n              <td>TypeScript Event Loop</td>\n              <td><code>svc-orchestrator</code> &rarr; <code>Content Script</code></td>\n              <td>Executes action plans; prompts user on high-severity mutations (payment, delete).</td>\n            </tr>\n            <tr>\n              <td><code>svc-gateway</code></td>\n              <td>Edge Ingress (Envoy)</td>\n              <td>TLS 1.3 \u00b7 Mutual Auth \u00b7 WSS/HTTPS</td>\n              <td>Client Extension &rarr; <code>svc-orchestrator</code></td>\n              <td>Rejects any incoming payload failing heuristic Indian PII checks.</td>\n            </tr>\n            <tr>\n              <td><code>svc-orchestrator</code></td>\n              <td>Private Kubernetes Cluster</td>\n              <td>FastAPI + LangGraph \u00b7 Python 3.11</td>\n              <td><code>svc-gateway</code> &harr; <code>svc-vlm-cloud</code>, <code>svc-policy</code></td>\n              <td>Multi-step goal decomposition; handles workflow state transitions.</td>\n            </tr>\n            <tr>\n              <td><code>svc-vlm-cloud</code></td>\n              <td>Air-Gapped Intranet GPU</td>\n              <td>vLLM \u00b7 Qwen2.5-VL-7B-Instruct</td>\n              <td><code>svc-orchestrator</code></td>\n              <td>Pure vision reasoning over sanitized scene; emits token-targeted action hypotheses.</td>\n            </tr>\n            <tr>\n              <td><code>svc-policy</code></td>\n              <td>Private Kubernetes Cluster</td>\n              <td>Open Policy Agent (OPA) \u00b7 Rego</td>\n              <td><code>svc-orchestrator</code></td>\n              <td>Enforces URL allowlists, rate limiting, and destructive action blocks.</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n    <div class=\"highlight-row\">\n      <div class=\"hl-card\"><span class=\"hl-icon\">&#x1F9E9;</span><div class=\"hl-title\">8 Microservices</div><div class=\"hl-body\">Each service is independently deployable, versioned, and has a single responsibility. Local services run inside the Chrome extension Manifest V3 service worker and offscreen document.</div></div>\n      <div class=\"hl-card\"><span class=\"hl-icon\">&#x1F510;</span><div class=\"hl-title\">Zero-Trust Boundary</div><div class=\"hl-body\">The local-to-cloud boundary enforces a strict \"sanitize-before-transmit\" contract. The Vault holds the only copy of the PII &#x2194; token mapping, never replicated to cloud.</div></div>\n      <div class=\"hl-card\"><span class=\"hl-icon\">&#x26A1;</span><div class=\"hl-title\">WebGPU Acceleration</div><div class=\"hl-body\">On-device vision models run entirely in WebGPU via ONNX Runtime Web, achieving ~120 ms inference on mid-range hardware with no GPU driver install needed.</div></div>\n    </div>",
  "s2": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F529;</div>\n      <h2 class=\"section-title\">Microservices Inventory</h2>\n    </div>\n    <p class=\"section-lead\">PRATYAKSHA decomposes into <strong>8 discrete services</strong> across two deployment zones: the browser-local layer (running inside the Chrome extension service worker and offscreen document) and the cloud compute layer (Docker containers on Kubernetes). Each service owns its data, exposes a versioned API, and can be deployed and scaled independently.</p>\n\n    <div class=\"callout blue\">\n      <div class=\"callout-icon\">&#x1F310;</div>\n      <div class=\"callout-body\"><div class=\"callout-title\">Zone A &mdash; Browser-Local Services (4 services)</div>Run entirely inside the Chrome Extension. No cloud dependency for these services. User data never leaves this boundary unless explicitly sanitized by the Vault.</div>\n    </div>\n    <div class=\"services-grid\">\n      <div class=\"service-card\">\n        <div class=\"service-card-header\"><div class=\"service-icon si-orange\">&#x1F5A5;&#xFE0F;</div><div><div class=\"service-name\">Extension Shell</div><div class=\"service-codename\">svc-ext-shell</div></div></div>\n        <p class=\"service-desc\">The UI orchestrator. Manages the Chrome Side Panel, popup interface, and command palette. Dispatches user intents to the Agent Runner. Renders sanitized action previews with a mandatory \"Confirm &amp; Execute\" step before any DOM mutation.</p>\n        <div class=\"service-meta\"><span class=\"meta-pill mp-tech\">Vanilla JS + Chrome APIs</span><span class=\"meta-pill mp-pattern\">Event-Driven</span><span class=\"meta-pill mp-port\">chrome.sidePanel</span></div>\n      </div>\n      <div class=\"service-card\">\n        <div class=\"service-card-header\"><div class=\"service-icon si-blue\">&#x1F441;&#xFE0F;</div><div><div class=\"service-name\">Vision Worker</div><div class=\"service-codename\">svc-vision-local</div></div></div>\n        <p class=\"service-desc\">Runs 4 INT8-quantized ONNX models via WebGPU inside a Chrome Offscreen Document (dedicated GPU context). Handles face detection, DBNet text region detection, Indic OCR, and content classification. Returns a typed scene graph with bounding boxes and confidence scores.</p>\n        <div class=\"service-meta\"><span class=\"meta-pill mp-tech\">ONNX Runtime Web</span><span class=\"meta-pill mp-tech\">WebGPU</span><span class=\"meta-pill mp-port\">Offscreen Document</span><span class=\"meta-pill mp-pattern\">Worker Thread</span></div>\n      </div>\n      <div class=\"service-card\">\n        <div class=\"service-card-header\"><div class=\"service-icon si-purple\">&#x1F512;</div><div><div class=\"service-name\">Vault Service</div><div class=\"service-codename\">svc-vault-local</div></div></div>\n        <p class=\"service-desc\">The privacy centrepiece. Stores all PII-to-token mappings in IndexedDB (AES-256-GCM encrypted at rest). Handles pseudonymisation (PII &#x2192; token) and rehydration (token &#x2192; PII) entirely locally. Tokens are session-scoped; one-way from the cloud's perspective.</p>\n        <div class=\"service-meta\"><span class=\"meta-pill mp-tech\">IndexedDB + Web Crypto</span><span class=\"meta-pill mp-tech\">AES-256-GCM</span><span class=\"meta-pill mp-pattern\">CQRS (local)</span></div>\n      </div>\n      <div class=\"service-card\">\n        <div class=\"service-card-header\"><div class=\"service-icon si-amber\">&#x1F916;</div><div><div class=\"service-name\">Agent Runner</div><div class=\"service-codename\">svc-agent-local</div></div></div>\n        <p class=\"service-desc\">Receives an action plan (JSON) from the cloud Orchestrator and executes it by dispatching real DOM events (MouseEvent, InputEvent, KeyboardEvent) into the active tab. Implements a rollback/undo stack. Enforces a mandatory human-approval gate for destructive actions.</p>\n        <div class=\"service-meta\"><span class=\"meta-pill mp-tech\">chrome.scripting</span><span class=\"meta-pill mp-tech\">Content Script</span><span class=\"meta-pill mp-pattern\">Command Pattern</span></div>\n      </div>\n    </div>\n\n    <div class=\"callout teal\">\n      <div class=\"callout-icon\">&#x2601;&#xFE0F;</div>\n      <div class=\"callout-body\"><div class=\"callout-title\">Zone B &mdash; Cloud Services (4 services)</div>Deployed as Docker containers in a Kubernetes cluster. These services <strong>ONLY</strong> ever see tokenized, sanitized data. They have zero knowledge of real PII values.</div>\n    </div>\n    <div class=\"services-grid\">\n      <div class=\"service-card\">\n        <div class=\"service-card-header\"><div class=\"service-icon si-purple\">&#x1F9E0;</div><div><div class=\"service-name\">Agent Orchestrator</div><div class=\"service-codename\">svc-orchestrator</div></div></div>\n        <p class=\"service-desc\">The cloud brain. Receives tokenized scene graphs and user task descriptions. Uses LangGraph to build an agentic reasoning loop with tool calls. Coordinates with the Cloud VLM Reasoner for visual understanding. Returns structured action plans (JSON) back to the local Agent Runner via WebSocket.</p>\n        <div class=\"service-meta\"><span class=\"meta-pill mp-tech\">FastAPI + LangGraph</span><span class=\"meta-pill mp-tech\">Python 3.12</span><span class=\"meta-pill mp-port\">:8001</span><span class=\"meta-pill mp-pattern\">Async / Event Loop</span></div>\n      </div>\n      <div class=\"service-card\">\n        <div class=\"service-card-header\"><div class=\"service-icon si-blue\">&#x1F52D;</div><div><div class=\"service-name\">Cloud VLM Reasoner</div><div class=\"service-codename\">svc-vlm-cloud</div></div></div>\n        <p class=\"service-desc\">Wraps a large vision-language model (Gemini 1.5 Pro or GPT-4o) to perform high-level scene understanding on the sanitized canvas. Only receives images where all PII regions are replaced by solid-colour redaction boxes. Returns structured JSON understanding of layout, intent, and actionable elements.</p>\n        <div class=\"service-meta\"><span class=\"meta-pill mp-tech\">Gemini API / OpenAI API</span><span class=\"meta-pill mp-port\">:8002</span><span class=\"meta-pill mp-pattern\">Adapter Pattern</span></div>\n      </div>\n      <div class=\"service-card\">\n        <div class=\"service-card-header\"><div class=\"service-icon si-green\">&#x1F4DC;</div><div><div class=\"service-name\">Policy Engine</div><div class=\"service-codename\">svc-policy</div></div></div>\n        <p class=\"service-desc\">Enforces organisational rules before any action is approved. Built on Open Policy Agent (OPA) with Rego rules. Can block actions targeting certain domains, disallow credential-autofill without user confirmation, and enforce rate limits. Acts as a mandatory sidecar to the Orchestrator.</p>\n        <div class=\"service-meta\"><span class=\"meta-pill mp-tech\">OPA + Rego</span><span class=\"meta-pill mp-port\">:8181 (OPA native)</span><span class=\"meta-pill mp-pattern\">Sidecar / Policy Mesh</span></div>\n      </div>\n      <div class=\"service-card\">\n        <div class=\"service-card-header\"><div class=\"service-icon si-teal\">&#x1F4CA;</div><div><div class=\"service-name\">Analytics &amp; Sync Ledger</div><div class=\"service-codename\">svc-analytics</div></div></div>\n        <p class=\"service-desc\">Records anonymised telemetry events (action types, latencies, error codes) in TimescaleDB. Maintains an immutable audit ledger of all agent actions (token-based, redacted), allowing users to review what the AI did on their behalf. Zero PII in logs.</p>\n        <div class=\"service-meta\"><span class=\"meta-pill mp-tech\">FastAPI + TimescaleDB</span><span class=\"meta-pill mp-port\">:8003</span><span class=\"meta-pill mp-pattern\">Event Sourcing</span></div>\n      </div>\n    </div>",
  "s3": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F30A;</div>\n      <h2 class=\"section-title\">7-Step Data-Flow Architecture</h2>\n    </div>\n    <p class=\"section-lead\">Every PRATYAKSHA request follows a strict 7-step pipeline. Steps 1&#x2013;3 are executed locally; steps 4&#x2013;5 happen in the cloud (with only sanitized data); steps 6&#x2013;7 rehydrate tokens back to real values locally before the agent acts.</p>\n        <!-- \u2500\u2500 MERMAID 7-STEP CHRONOLOGICAL SEQUENCE \u2500\u2500 -->\n    <div class=\"mermaid-wrapper\">\n      <div class=\"mermaid-header\">\n        <div class=\"mermaid-title\">\n          <span>\u23f1\ufe0f The 7-Step Privacy-Preserving Execution Sequence</span>\n        </div>\n        <div class=\"mermaid-controls\">\n          <button class=\"mermaid-btn\" id=\"seqZoomInBtn\" title=\"Zoom In\">\ud83d\udd0d +</button>\n          <button class=\"mermaid-btn\" id=\"seqZoomOutBtn\" title=\"Zoom Out\">\ud83d\udd0d &minus;</button>\n          <button class=\"mermaid-btn\" id=\"seqZoomResetBtn\" title=\"Reset View\">&#x23FA; Reset</button>\n        </div>\n        <div class=\"mermaid-meta\">\n          <span class=\"mermaid-tag mt-orange\">Step-by-Step Call Stack</span>\n          <span class=\"mermaid-tag mt-purple\">Reversible Vault Loop</span>\n          <span class=\"mermaid-tag mt-green\">End-to-End Latency: &lt;1.2s</span>\n        </div>\n      </div>\n\n      <div class=\"mermaid-box\" id=\"mermaidBoxSeq\">\n        <pre class=\"mermaid\" id=\"mermaidPreSeq\">\nsequenceDiagram\n    autonumber\n    actor User as \ud83d\udc64 User / Operator\n    participant Tab as \ud83c\udf10 Target Tab DOM\n    participant Content as \ud83d\udcdc Content Script\n    participant Offscreen as \u26a1 WebGPU Privacy Shield\n    participant Vault as \ud83d\udd10 Local Vault Service\n    participant Gateway as \ud83d\udeaa API Gateway\n    participant Orchestrator as \ud83e\udde0 Orchestrator (LangGraph)\n    participant VLM as \ud83e\udd16 Sovereign VLM (vLLM)\n\n    User->>Content: 1. Submit task intent via Side Panel (\"Fill supplier bid\")\n    Content->>Tab: 2. Traverse interactive elements & computed styles\n    Tab-->>Content: 3. Return structured DOM scene tree\n    Content->>Offscreen: 4. chrome.tabs.captureVisibleTab() + DOM scene tree\n    Note over Offscreen: Stage A: 8x8 dHash skips redundant static tiles<br/>Stage B: DBNet detects text regions in PDFs/Canvases<br/>Stage C: Ultra-Light-Face flags biometrics<br/>Stage D: CRNN OCR extracts Devanagari + Latin strings<br/>Stage E: Verhoeff algorithm validates 12-digit Aadhaar\n    Offscreen->>Vault: 5. Register verified PII {type: 'AADHAAR', raw: '5489-1234-8901', bbox}\n    Vault-->>Offscreen: 6. Return typed token \u27e8AADHAAR_01\u27e9\n    Note over Offscreen: Stage F: 4px safety halo dilation inpainting on canvas<br/>Stage G: SHA-256 Merkle egress hash proof generated\n    Offscreen->>Gateway: 7. POST /v1/agent/task (Sanitized canvas + Tokenized scene + Hash proof)\n    Note over Gateway: Ingress inspection: Verify TLS 1.3 + JWT<br/>Heuristic check: Zero raw PII allowed across boundary\n    Gateway->>Orchestrator: 8. Forward sanitized task context\n    Orchestrator->>VLM: 9. Prompt Qwen2.5-VL with sanitized image & token IDs\n    Note over VLM: Model inspects layout & synthetic tokens<br/>Plans next step: Click input box \u27e8AADHAAR_01\u27e9\n    VLM-->>Orchestrator: 10. Emits structured action plan JSON\n    Orchestrator-->>Content: 11. Stream Action Plan frame via WebSocket\n    Note over Content: Intercept action targeting \u27e8AADHAAR_01\u27e9\n    Content->>Vault: 12. Query real decrypted value for token \u27e8AADHAAR_01\u27e9\n    Vault-->>Content: 13. Return real Aadhaar string (in local RAM only)\n    Content->>Tab: 14. dispatchEvent(new InputEvent('input', {data: realValue}))\n    Tab-->>User: 15. Real-time visual confirmation in portal\n        </pre>\n        <div class=\"mermaid-canvas-hint\">\n          <span>\ud83d\udd90\ufe0f Drag to Pan</span>\n          <span>\u00b7</span>\n          <span>\ud83d\udd0d Pinch or Scroll to Zoom</span>\n        </div>\n      </div>\n    </div>\n    </div>\n    <div class=\"card\"><div class=\"card-title\">&#x1F4F8; Step 1 &mdash; PERCEIVE: Dual-Channel Screen Understanding</div><div class=\"card-body\"><strong>Channel A &mdash; DOM Extraction:</strong> The content script enumerates all interactive and semantic DOM nodes (inputs, buttons, headings, paragraphs, tables), extracting text content, ARIA labels, bounding boxes, and computed styles to produce a structured node tree.<br/><br/><strong>Channel B &mdash; Pixel Capture:</strong> <span class=\"mono\">chrome.tabs.captureVisibleTab()</span> captures the current viewport as a high-resolution PNG. This is passed directly to the Vision Worker &mdash; it <strong>NEVER</strong> leaves the local context before sanitization.<br/><br/><strong>Non-DOM Content (Key Innovation):</strong> PDFs rendered by the browser, embedded iframes, canvas elements, and SVG infographics cannot be read by DOM extraction alone. The Vision Worker's pixel pipeline handles these via the OCR + detection stack &mdash; this is the core problem this PS solves.</div></div>\n    <div class=\"card\"><div class=\"card-title\">&#x1F441;&#xFE0F; Step 2 &mdash; DETECT: Vision Worker Model Pipeline</div><div class=\"card-body\">The Vision Worker runs 4 models in sequence, each taking ~30 ms on WebGPU (total ~120 ms):<br/><br/><strong>&#x2460; Face Detector</strong> &mdash; YOLOv8-nano INT8: Detects all faces, produces bounding boxes. All detected faces are registered as <span class=\"mono\">&#x27E8;FACE_N&#x27E9;</span> tokens in the Vault.<br/><strong>&#x2461; Text Region Detector</strong> &mdash; DBNet-small: Detects all text regions including regions inside images/PDFs that DOM can't reach.<br/><strong>&#x2462; Indic OCR</strong> &mdash; CRNN with Devanagari + Latin: Reads text from detected regions. Pattern-matches against PII regexes (Aadhaar: 12-digit, PAN: AAAAA-9999-A, phone numbers, bank accounts).<br/><strong>&#x2463; Content Classifier</strong> &mdash; MobileNetV4-tiny: Classifies screen context (BANKING, MEDICAL, GOVERNMENT, GENERAL) to apply appropriate sanitization policy level.</div></div>\n    <div class=\"card\"><div class=\"card-title\">&#x1F512; Step 3 &mdash; SANITIZE: The Vault Service in Action</div><div class=\"card-body\"><strong>A. Image Redaction:</strong> Draws solid-colour fills (distinct per category: orange for faces, blue for Aadhaar, red for financial) over each detected PII bounding box on the captured canvas. The redacted canvas is what gets transmitted.<br/><br/><strong>B. Token Registry:</strong> For each detected PII item, generates a deterministic session-scoped token (e.g., <span class=\"mono\">&#x27E8;AADHAAR_01&#x27E9;</span>). Stores <span class=\"mono\">token &#x2192; {realValue, boundingBox, type, confidence}</span> in AES-256-GCM encrypted IndexedDB. Replaces real values in the scene graph JSON with their tokens.<br/><br/><strong>Output:</strong> A sanitized canvas (PNG) + a tokenized scene graph (JSON). These are the <em>only</em> artefacts that cross the local boundary.</div></div>\n    <div class=\"card\"><div class=\"card-title\">&#x1F9E0; Steps 4&#x2013;5 &mdash; REASON + PLAN: Cloud Intelligence Loop</div><div class=\"card-body\">The sanitized canvas + tokenized scene graph are sent to the Cloud VLM Reasoner via HTTPS POST through the API Gateway. The VLM returns structured understanding (layout, semantics, actionable elements &mdash; all referencing tokens, not real data). The Agent Orchestrator runs a LangGraph planning loop to produce a JSON Action Plan: a sequence of typed actions &mdash; <span class=\"mono\">CLICK(selector)</span>, <span class=\"mono\">TYPE(token_or_literal)</span>, <span class=\"mono\">SCROLL(delta)</span>, <span class=\"mono\">WAIT(ms)</span>, <span class=\"mono\">ASSERT(condition)</span>. The Policy Engine intercepts the plan before it is returned, checking each action against OPA rules.</div></div>\n    <div class=\"card\"><div class=\"card-title\">&#x1F504; Steps 6&#x2013;7 &mdash; REHYDRATE + EXECUTE: Local Action</div><div class=\"card-body\">The Action Plan arrives at the local Agent Runner still using tokens. The Vault Service is queried for each token to substitute the real value back &mdash; this happens entirely locally. The cloud never learns the real values. If a token is not found (tampered plan or hallucinated token), the action is blocked and the user is alerted. Rehydrated actions are then dispatched as real DOM events: <span class=\"mono\">dispatchEvent(new MouseEvent('click', ...))</span>, <span class=\"mono\">dispatchEvent(new InputEvent('input', ...))</span>, with each step logged to the local audit ledger and optionally synced (token-based) to the cloud ledger.</div></div>",
  "s4": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F4E1;</div>\n      <h2 class=\"section-title\">API Contract Specification</h2>\n    </div>\n    <p class=\"section-lead\">All cloud-facing APIs use HTTPS with TLS 1.3. WebSocket connections use WSS. All requests must carry a short-lived JWT (15-minute expiry) issued by the Auth Service. Cloud services only accept requests through the API Gateway.</p>\n    <div class=\"callout blue\">\n      <div class=\"callout-icon\">&#x1F511;</div>\n      <div class=\"callout-body\"><div class=\"callout-title\">API Gateway Base URL</div><span class=\"mono\">https://api.pratyaksha.isro.gov.in/v1/</span> &middot; All endpoints versioned under <span class=\"mono\">/v1/</span>. Breaking changes increment to <span class=\"mono\">/v2/</span> with 90-day deprecation notice.</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"card-title\">&#x1F511; Auth Service API</div>\n      <div class=\"card-body\">\n        <table class=\"api-table\">\n          <thead><tr><th>Method</th><th>Endpoint</th><th>Description</th><th>Returns</th></tr></thead>\n          <tbody>\n            <tr><td><span class=\"method POST\">POST</span></td><td class=\"endpoint\">/auth/token</td><td>Exchange device fingerprint + credentials for JWT pair</td><td>JWT access (15m) + refresh (7d)</td></tr>\n            <tr><td><span class=\"method POST\">POST</span></td><td class=\"endpoint\">/auth/refresh</td><td>Rotate JWT access token using refresh token</td><td>New access JWT</td></tr>\n            <tr><td><span class=\"method POST\">POST</span></td><td class=\"endpoint\">/auth/revoke</td><td>Revoke refresh token (logout / extension uninstall)</td><td>204 No Content</td></tr>\n            <tr><td><span class=\"method GET\">GET</span></td><td class=\"endpoint\">/auth/me</td><td>Get current user profile and active session info</td><td>User object (JSON)</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n    <div class=\"card\">\n      <div class=\"card-title\">&#x1F9E0; Agent Orchestrator API</div>\n      <div class=\"card-body\">\n        <table class=\"api-table\">\n          <thead><tr><th>Method</th><th>Endpoint</th><th>Description</th><th>Returns</th></tr></thead>\n          <tbody>\n            <tr><td><span class=\"method POST\">POST</span></td><td class=\"endpoint\">/agent/task</td><td>Submit new agentic task with sanitized canvas + tokenized scene graph + user intent</td><td>task_id (UUID)</td></tr>\n            <tr><td><span class=\"method WS\">WS</span></td><td class=\"endpoint\">/agent/stream/{task_id}</td><td>Real-time stream of action plan steps and reasoning trace as NDJSON frames</td><td>ActionPlan frames</td></tr>\n            <tr><td><span class=\"method GET\">GET</span></td><td class=\"endpoint\">/agent/task/{task_id}</td><td>Poll final action plan when WebSocket is not available</td><td>ActionPlan JSON</td></tr>\n            <tr><td><span class=\"method POST\">POST</span></td><td class=\"endpoint\">/agent/feedback</td><td>Submit user feedback on action result (thumbs up/down, correction text)</td><td>202 Accepted</td></tr>\n            <tr><td><span class=\"method DELETE\">DELETE</span></td><td class=\"endpoint\">/agent/task/{task_id}</td><td>Cancel an in-flight task (user clicked Stop)</td><td>204 No Content</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n    <div class=\"card\">\n      <div class=\"card-title\">&#x1F4CA; Analytics &amp; Ledger API</div>\n      <div class=\"card-body\">\n        <table class=\"api-table\">\n          <thead><tr><th>Method</th><th>Endpoint</th><th>Description</th><th>Returns</th></tr></thead>\n          <tbody>\n            <tr><td><span class=\"method POST\">POST</span></td><td class=\"endpoint\">/analytics/event</td><td>Emit anonymised telemetry event (action type, latency, success) &mdash; no PII</td><td>201 Created</td></tr>\n            <tr><td><span class=\"method GET\">GET</span></td><td class=\"endpoint\">/ledger/history</td><td>Paginated audit log of all agent actions for current user (token-based)</td><td>Array of ActionRecord</td></tr>\n            <tr><td><span class=\"method DELETE\">DELETE</span></td><td class=\"endpoint\">/ledger/history</td><td>Delete all audit records for user (GDPR/DPDP right to erasure)</td><td>204 No Content</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n    <div class=\"card\">\n      <div class=\"card-title\">&#x1F50C; WebSocket Action Plan Frame Schema</div>\n      <div class=\"card-body\">\n        <div class=\"code-block\"><code><span class=\"code-comment\">// Streamed as NDJSON over WSS /agent/stream/{task_id}</span>\n{\n  <span class=\"code-key\">\"frame_type\"</span>: <span class=\"code-str\">\"ACTION_STEP\"</span> | <span class=\"code-str\">\"REASONING\"</span> | <span class=\"code-str\">\"DONE\"</span> | <span class=\"code-str\">\"ERROR\"</span>,\n  <span class=\"code-key\">\"step_index\"</span>: <span class=\"code-type\">number</span>,\n  <span class=\"code-key\">\"action\"</span>: {\n    <span class=\"code-key\">\"type\"</span>: <span class=\"code-str\">\"CLICK\"</span> | <span class=\"code-str\">\"TYPE\"</span> | <span class=\"code-str\">\"SCROLL\"</span> | <span class=\"code-str\">\"WAIT\"</span> | <span class=\"code-str\">\"NAVIGATE\"</span> | <span class=\"code-str\">\"ASSERT\"</span>,\n    <span class=\"code-key\">\"target_selector\"</span>: <span class=\"code-str\">\"string (CSS / XPath)\"</span>,\n    <span class=\"code-key\">\"value\"</span>: <span class=\"code-str\">\"string | &lt;TOKEN_REF&gt;\"</span>,\n    <span class=\"code-key\">\"requires_approval\"</span>: <span class=\"code-type\">boolean</span>,\n    <span class=\"code-key\">\"is_destructive\"</span>: <span class=\"code-type\">boolean</span>\n  },\n  <span class=\"code-key\">\"reasoning_trace\"</span>: <span class=\"code-str\">\"string (optional)\"</span>,\n  <span class=\"code-key\">\"policy_verdict\"</span>: <span class=\"code-str\">\"ALLOW\"</span> | <span class=\"code-str\">\"BLOCK\"</span> | <span class=\"code-str\">\"REQUIRE_CONFIRMATION\"</span>\n}</code></div>\n      </div>\n    </div>",
  "s5": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F6E1;&#xFE0F;</div>\n      <h2 class=\"section-title\">Security Architecture</h2>\n    </div>\n    <p class=\"section-lead\">PRATYAKSHA is designed against the <strong>OWASP Top 10</strong>, <strong>India's DPDP Act 2023</strong>, and relevant <strong>ISRO data classification policies</strong>. Security operates at three levels: threat identification, technical controls, and verification/audit.</p>\n    <div class=\"security-matrix\">\n      <div class=\"sec-card threat\">\n        <div class=\"sec-label\">&#x1F534; Threat Model</div>\n        <div class=\"sec-item\"><div class=\"sec-dot red\"></div><div>Malicious cloud provider sniffing screen data</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot red\"></div><div>Extension-to-extension XSS / message injection</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot red\"></div><div>Supply chain attack on ONNX model weights</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot red\"></div><div>Prompt injection via malicious web page content</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot red\"></div><div>Rogue action plan from compromised cloud service</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot red\"></div><div>IndexedDB vault exfiltration by other extensions</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot red\"></div><div>MitM on sanitized canvas upload (intercept + reassembly)</div></div>\n      </div>\n      <div class=\"sec-card control\">\n        <div class=\"sec-label\">&#x1F7E2; Technical Controls</div>\n        <div class=\"sec-item\"><div class=\"sec-dot green\"></div><div>Vault encrypts all PII with AES-256-GCM before IndexedDB write</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot green\"></div><div>Strict CSP: <span class=\"mono\" style=\"font-size:10.5px\">script-src 'self'</span> \u2014 no inline scripts</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot green\"></div><div>ONNX model weights verified by SHA-256 hash on every load</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot green\"></div><div>Content sanitizer strips all HTML from page text before VLM prompt</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot green\"></div><div>Action plans validated against JSON Schema before execution</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot green\"></div><div>Isolated world content scripts (chrome API boundary enforced)</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot green\"></div><div>All cloud comms over TLS 1.3 with certificate pinning</div></div>\n      </div>\n      <div class=\"sec-card verify\">\n        <div class=\"sec-label\">&#x1F535; Verification &amp; Audit</div>\n        <div class=\"sec-item\"><div class=\"sec-dot blue\"></div><div>Every action logged to immutable Ledger (token-based)</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot blue\"></div><div>Policy Engine (OPA) audits every action plan before execution</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot blue\"></div><div>User can review full session history in Side Panel</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot blue\"></div><div>Destructive actions always require explicit user confirmation</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot blue\"></div><div>Monthly automated security scan via Snyk + Dependabot</div></div>\n        <div class=\"sec-item\"><div class=\"sec-dot blue\"></div><div>DPDP Act 2023 compliance &mdash; right to erasure via API</div></div>\n      </div>\n    </div>\n    <div class=\"callout red\">\n      <div class=\"callout-icon\">&#x26D4;</div>\n      <div class=\"callout-body\"><div class=\"callout-title\">Hard Security Invariants &mdash; Must NEVER Be Violated</div>\n        <strong>1.</strong> Raw captured screenshots are never sent over any network.<br/>\n        <strong>2.</strong> The PII &#x2194; Token mapping table never leaves IndexedDB (no sync, no backup to cloud).<br/>\n        <strong>3.</strong> The extension never auto-executes actions for banking/medical sites without user confirmation, regardless of policy verdict.<br/>\n        <strong>4.</strong> Model weight integrity check failure = fail-closed (refuse to process, alert user immediately).\n      </div>\n    </div>",
  "s6": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F5C4;&#xFE0F;</div>\n      <h2 class=\"section-title\">Data Storage Design</h2>\n    </div>\n    <p class=\"section-lead\">PRATYAKSHA uses a split storage strategy: sensitive data stays entirely local (browser); anonymized telemetry and audit logs go to cloud. No cloud database ever holds real PII.</p>\n    <div class=\"services-grid\">\n      <div class=\"service-card\">\n        <div class=\"service-card-header\"><div class=\"service-icon si-purple\">&#x1F512;</div><div><div class=\"service-name\">Local Vault Store</div><div class=\"service-codename\">IndexedDB &middot; Browser-only</div></div></div>\n        <p class=\"service-desc\">Stores encrypted PII-to-token mappings. AES-256-GCM with key derived from device fingerprint + user PIN via PBKDF2 (300k iterations). Session-scoped by default: tokens expire with the browser session. Schema versioned for safe migration.</p>\n        <div class=\"service-meta\"><span class=\"meta-pill mp-tech\">IndexedDB + Web Crypto API</span><span class=\"meta-pill mp-tech\">AES-256-GCM</span></div>\n      </div>\n      <div class=\"service-card\">\n        <div class=\"service-card-header\"><div class=\"service-icon si-blue\">&#x1F534;</div><div><div class=\"service-name\">Token Cache</div><div class=\"service-codename\">Redis &middot; Cloud</div></div></div>\n        <p class=\"service-desc\">Short-lived server-side cache for session tokens (JWT rotation, rate-limit counters, in-flight task state). Contains ZERO PII &mdash; only session identifiers, task IDs, and action plan drafts. All keys have TTL &le; 24h.</p>\n        <div class=\"service-meta\"><span class=\"meta-pill mp-tech\">Redis 7 (ElastiCache)</span><span class=\"meta-pill mp-pattern\">TTL-based eviction</span></div>\n      </div>\n      <div class=\"service-card\">\n        <div class=\"service-card-header\"><div class=\"service-icon si-teal\">&#x1F5C3;&#xFE0F;</div><div><div class=\"service-name\">Audit Ledger</div><div class=\"service-codename\">PostgreSQL &middot; Cloud</div></div></div>\n        <p class=\"service-desc\">Stores per-user audit records of all agent actions: action_type, domain, timestamp, policy_verdict, success/failure. ALL values are token-based or anonymised. Indexed on user_id + timestamp. Soft-deletable for DPDP compliance.</p>\n        <div class=\"service-meta\"><span class=\"meta-pill mp-tech\">PostgreSQL 16 (RDS)</span><span class=\"meta-pill mp-pattern\">Event Sourcing</span></div>\n      </div>\n      <div class=\"service-card\">\n        <div class=\"service-card-header\"><div class=\"service-icon si-amber\">&#x1F4C8;</div><div><div class=\"service-name\">Telemetry Store</div><div class=\"service-codename\">TimescaleDB &middot; Cloud</div></div></div>\n        <p class=\"service-desc\">Time-series storage for anonymised performance metrics: per-model inference latencies, task success rates, policy block rates, daily active users. Feeds the Grafana dashboard. Raw events not stored beyond 24h.</p>\n        <div class=\"service-meta\"><span class=\"meta-pill mp-tech\">TimescaleDB (PostgreSQL)</span><span class=\"meta-pill mp-pattern\">Continuous Aggregation</span></div>\n      </div>\n    </div>\n    <div class=\"code-block\"><code><span class=\"code-comment\">-- Audit Ledger schema (PostgreSQL) \u2014 No PII fields exist in this table</span>\n<span class=\"code-key\">CREATE TABLE</span> agent_actions (\n  id             <span class=\"code-type\">UUID PRIMARY KEY DEFAULT gen_random_uuid()</span>,\n  user_id        <span class=\"code-type\">UUID NOT NULL</span>,    <span class=\"code-comment\">-- hashed user identifier, never raw</span>\n  task_id        <span class=\"code-type\">UUID NOT NULL</span>,\n  action_type    <span class=\"code-type\">TEXT NOT NULL</span>,    <span class=\"code-comment\">-- CLICK, TYPE, SCROLL, etc.</span>\n  domain         <span class=\"code-type\">TEXT</span>,            <span class=\"code-comment\">-- domain only, no full URL path</span>\n  policy_verdict <span class=\"code-type\">TEXT NOT NULL</span>,    <span class=\"code-comment\">-- ALLOW / BLOCK / REQUIRE_CONFIRMATION</span>\n  success        <span class=\"code-type\">BOOLEAN</span>,\n  latency_ms     <span class=\"code-type\">INTEGER</span>,\n  created_at     <span class=\"code-type\">TIMESTAMPTZ DEFAULT now()</span>,\n  deleted_at     <span class=\"code-type\">TIMESTAMPTZ</span>       <span class=\"code-comment\">-- DPDP soft-delete for right to erasure</span>\n);</code></div>",
  "s7": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F680;</div>\n      <h2 class=\"section-title\">Deployment Topology</h2>\n    </div>\n    <p class=\"section-lead\">Cloud services are deployed as Docker containers in a managed Kubernetes cluster. The Chrome Extension is distributed via the Chrome Web Store (or enterprise policy push for ISRO internal deployment). Cloudflare Workers serve as the edge API Gateway for low latency.</p>\n    <div class=\"deploy-grid\">\n      <div class=\"deploy-card\">\n        <div class=\"deploy-zone zone-local\">&#x1F4CD; Browser (Local)</div>\n        <div class=\"deploy-title\">Chrome Extension Package</div>\n        <div class=\"deploy-item\">Manifest V3 (.crx / Web Store)</div>\n        <div class=\"deploy-item\">Service Worker (bg logic + Vision Worker)</div>\n        <div class=\"deploy-item\">Offscreen Document (WebGPU GPU context)</div>\n        <div class=\"deploy-item\">Content Scripts (per-tab DOM access)</div>\n        <div class=\"deploy-item\">Side Panel UI (Vanilla JS + CSS)</div>\n        <div class=\"deploy-item\">IndexedDB Vault (encrypted PII store)</div>\n        <div class=\"deploy-item\">ONNX models (~45 MB, cached in CacheStorage)</div>\n      </div>\n      <div class=\"deploy-card\">\n        <div class=\"deploy-zone zone-cdn\">&#x1F310; Edge (Cloudflare Workers)</div>\n        <div class=\"deploy-title\">API Gateway + Auth Edge</div>\n        <div class=\"deploy-item\">JWT validation at edge (zero-latency auth)</div>\n        <div class=\"deploy-item\">Rate limiting (100 req/min per user)</div>\n        <div class=\"deploy-item\">Request routing to regional K8s cluster</div>\n        <div class=\"deploy-item\">DDoS protection + WAF rules</div>\n        <div class=\"deploy-item\">TLS 1.3 termination + certificate pinning</div>\n      </div>\n      <div class=\"deploy-card\">\n        <div class=\"deploy-zone zone-cloud\">&#x2601;&#xFE0F; Cloud (Kubernetes)</div>\n        <div class=\"deploy-title\">Compute Plane</div>\n        <div class=\"deploy-item\">svc-orchestrator (FastAPI, 2&#x2013;8 pods HPA)</div>\n        <div class=\"deploy-item\">svc-vlm-cloud (Gemini/OpenAI adapter, 1&#x2013;4 pods)</div>\n        <div class=\"deploy-item\">svc-policy (OPA sidecar, injected per pod)</div>\n        <div class=\"deploy-item\">svc-analytics (FastAPI + TimescaleDB, 2 pods)</div>\n        <div class=\"deploy-item\">svc-auth (Keycloak, HA pair)</div>\n        <div class=\"deploy-item\">RabbitMQ (async task queue between services)</div>\n      </div>\n      <div class=\"deploy-card\">\n        <div class=\"deploy-zone zone-db\">&#x1F5C3;&#xFE0F; Data Plane</div>\n        <div class=\"deploy-title\">Persistence Layer</div>\n        <div class=\"deploy-item\">PostgreSQL 16 (RDS Multi-AZ, ap-south-1)</div>\n        <div class=\"deploy-item\">TimescaleDB (EC2, auto-snapshot daily)</div>\n        <div class=\"deploy-item\">Redis 7 (ElastiCache cluster mode, cross-AZ)</div>\n        <div class=\"deploy-item\">S3 (sanitized canvas artifacts, 7-day lifecycle)</div>\n        <div class=\"deploy-item\">Vault Key Store &mdash; NOT cloud (stays local only)</div>\n      </div>\n    </div>\n    <div class=\"callout green\">\n      <div class=\"callout-icon\">&#x1F433;</div>\n      <div class=\"callout-body\"><div class=\"callout-title\">Container Build &amp; Deploy Pipeline</div>GitHub Actions &#x2192; Docker Build (multi-stage, distroless final image) &#x2192; Push to ECR &#x2192; Helm Chart upgrade &#x2192; Kubernetes rolling deploy &#x2192; Smoke test &#x2192; Grafana canary monitoring. Total deploy time: ~8 minutes end-to-end.</div>\n    </div>",
  "s8": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F4C8;</div>\n      <h2 class=\"section-title\">Scalability &amp; Resilience</h2>\n    </div>\n    <p class=\"section-lead\">PRATYAKSHA scales from a 10-user prototype to a 100,000+ user government deployment. The on-device vision layer scales infinitely (each user runs their own model). The cloud layer scales horizontally with Kubernetes HPA.</p>\n    <div class=\"metric-grid\">\n      <div class=\"metric-card\"><div class=\"metric-value\">&lt;200ms</div><div class=\"metric-label\">Local Vision Pipeline</div><div class=\"metric-sub\">WebGPU ONNX (mid-range GPU)</div></div>\n      <div class=\"metric-card\"><div class=\"metric-value\">&lt;800ms</div><div class=\"metric-label\">End-to-End Task</div><div class=\"metric-sub\">P95 latency (VLM + plan)</div></div>\n      <div class=\"metric-card\"><div class=\"metric-value\">99.9%</div><div class=\"metric-label\">Availability SLA</div><div class=\"metric-sub\">Cloud services (3-nines)</div></div>\n      <div class=\"metric-card\"><div class=\"metric-value\">&#x221E;</div><div class=\"metric-label\">Vision Scaling</div><div class=\"metric-sub\">Runs on user's own device</div></div>\n    </div>\n    <div class=\"services-grid\">\n      <div class=\"card\"><div class=\"card-title\">&#x26A1; Horizontal Scaling &mdash; Orchestrator</div><div class=\"card-body\">Kubernetes HPA scales svc-orchestrator from 2 &#x2192; 8 pods based on CPU (target 70%) and custom RabbitMQ queue depth metric. Each pod is stateless &mdash; task state stored in Redis. P95 latency budget: 500ms for planning step. Load tested to 5,000 concurrent tasks.</div></div>\n      <div class=\"card\"><div class=\"card-title\">&#x1F501; Circuit Breakers &amp; Fallbacks</div><div class=\"card-body\">If the Cloud VLM Reasoner is unavailable, the system falls back to DOM-only analysis (skipping visual understanding). If the Policy Engine is unreachable, the system fails-closed &mdash; no actions are executed without a policy verdict. All fallback paths are logged and surfaced to the user.</div></div>\n      <div class=\"card\"><div class=\"card-title\">&#x1F4E6; Model Caching Strategy</div><div class=\"card-body\">ONNX model files (~45 MB combined) are cached in Chrome's CacheStorage API on first install. Subsequent sessions load from cache in &lt;100ms. Model updates are version-controlled and only re-downloaded when the extension updates. SHA-256 integrity verified on every load.</div></div>\n      <div class=\"card\"><div class=\"card-title\">&#x1F30D; Multi-Region Readiness</div><div class=\"card-body\">Primary in ap-south-1 (Mumbai) for ISRO data residency compliance, failover to ap-southeast-1 (Singapore). PostgreSQL uses RDS Multi-AZ. Redis uses ElastiCache cluster mode with cross-AZ replication. RTO: 5 minutes, RPO: 0 (synchronous replication).</div></div>\n    </div>",
  "s9": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F4CB;</div>\n      <h2 class=\"section-title\">Architecture Decision Records (ADRs)</h2>\n    </div>\n    <p class=\"section-lead\">Key architectural decisions are documented here to preserve the reasoning behind each choice. This prevents re-litigating settled decisions and helps new team members understand the why, not just the what.</p>\n    <div class=\"adr-card decided\">\n      <div class=\"adr-id\">ADR-001</div>\n      <div class=\"adr-title\">Use ONNX Runtime Web + WebGPU for on-device vision inference</div>\n      <div class=\"adr-status decided\">&#x2705; Decided</div>\n      <div class=\"adr-body\"><strong>Context:</strong> Need to run face detection, text detection, and OCR inside the browser without native software installation. <strong>Decision:</strong> ONNX Runtime Web with WebGPU execution provider. Models are quantized to INT8. <strong>Alternatives rejected:</strong> TensorFlow.js (larger bundle, slower), WebNN (insufficient browser support in 2024), native app (breaks the browser-extension requirement). <strong>Trade-off:</strong> ~45 MB model bundle on first load; mitigated by CacheStorage caching.</div>\n    </div>\n    <div class=\"adr-card decided\">\n      <div class=\"adr-id\">ADR-002</div>\n      <div class=\"adr-title\">Store PII vault in IndexedDB with AES-256-GCM (not chrome.storage)</div>\n      <div class=\"adr-status decided\">&#x2705; Decided</div>\n      <div class=\"adr-body\"><strong>Context:</strong> Need to store PII-to-token mappings securely, locally. <strong>Decision:</strong> IndexedDB with Web Crypto API (AES-256-GCM). Key derived via PBKDF2 from device fingerprint + user PIN. <strong>Alternatives rejected:</strong> chrome.storage.local (not encrypted, may sync to Google servers in sync mode), localStorage (size limit, not encrypted). <strong>Trade-off:</strong> Higher implementation complexity; mitigated by an encapsulated Vault Service class.</div>\n    </div>\n    <div class=\"adr-card decided\">\n      <div class=\"adr-id\">ADR-003</div>\n      <div class=\"adr-title\">Use LangGraph for cloud agentic orchestration (not custom FSM)</div>\n      <div class=\"adr-status decided\">&#x2705; Decided</div>\n      <div class=\"adr-body\"><strong>Context:</strong> Need a robust, debuggable agentic loop for planning multi-step browser actions. <strong>Decision:</strong> LangGraph with an explicit state graph. Each node = one planning step. Edges represent conditional transitions. <strong>Alternatives rejected:</strong> Raw LLM loop (no state management, hard to debug), AutoGen (too opinionated, heavy). <strong>Trade-off:</strong> Python-only; mitigated because Orchestrator service is isolated behind an API.</div>\n    </div>\n    <div class=\"adr-card decided\">\n      <div class=\"adr-id\">ADR-004</div>\n      <div class=\"adr-title\">Use Open Policy Agent (OPA) as the authorization sidecar</div>\n      <div class=\"adr-status decided\">&#x2705; Decided</div>\n      <div class=\"adr-body\"><strong>Context:</strong> Need flexible, auditable policy enforcement for agent actions. <strong>Decision:</strong> OPA with Rego policies, deployed as a sidecar to svc-orchestrator. Policies stored in git and hot-reloaded via OPA bundle server. <strong>Alternatives rejected:</strong> Hardcoded if/else logic (not auditable), XACML (too complex). <strong>Trade-off:</strong> Additional ~5ms latency per decision; acceptable given security benefit.</div>\n    </div>\n    <div class=\"adr-card proposed\">\n      <div class=\"adr-id\">ADR-005</div>\n      <div class=\"adr-title\">Offscreen Document for WebGPU Vision inference context isolation</div>\n      <div class=\"adr-status proposed\">&#x1F535; Proposed / Under Review</div>\n      <div class=\"adr-body\"><strong>Context:</strong> Chrome Manifest V3 Service Workers cannot directly access WebGPU (no GPU context). Need a persistent GPU context for ONNX models. <strong>Proposed:</strong> Use <span class=\"mono\">chrome.offscreen.createDocument()</span> with a dedicated HTML page holding the WebGPU context and ONNX session. <strong>Risk:</strong> Offscreen documents (Chrome 109+) have some lifecycle edge cases. <strong>Mitigation:</strong> Fallback to WASM execution provider on WebGPU failure.</div>\n    </div>",
  "s10": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F5D3;&#xFE0F;</div>\n      <h2 class=\"section-title\">Build Roadmap &mdash; Sprint Plan</h2>\n    </div>\n    <p class=\"section-lead\">The project is divided into 4 phases aligned with SIH 2026 evaluation milestones. Each phase delivers a demonstrable working increment.</p>\n    <div class=\"timeline\">\n      <div class=\"timeline-item\">\n        <div class=\"timeline-dot orange\"></div>\n        <div class=\"timeline-phase\" style=\"color:var(--isro-orange)\">Phase 1 &mdash; Foundation (Weeks 1&#x2013;3) &middot; Local Pipeline MVP</div>\n        <div class=\"timeline-content\">Set up Extension Shell (Manifest V3). Implement <span class=\"mono\">chrome.tabs.captureVisibleTab()</span> + DOM extraction pipeline. Integrate ONNX Runtime Web + YOLOv8-nano face detector (WebGPU). Build Vault Service with IndexedDB + AES-256-GCM. <strong>Deliverable:</strong> A working extension that captures a screenshot, detects faces, and generates a tokenized scene graph locally.</div>\n      </div>\n      <div class=\"timeline-item\">\n        <div class=\"timeline-dot blue\"></div>\n        <div class=\"timeline-phase\" style=\"color:var(--color-info)\">Phase 2 &mdash; Full Vision Stack (Weeks 4&#x2013;6) &middot; All 4 Models</div>\n        <div class=\"timeline-content\">Add DBNet text detector, Indic CRNN OCR, and MobileNetV4 content classifier. Build the model orchestration pipeline in the Offscreen Document. Implement PII regex engine. Add sanitized canvas redaction. Test against government document PDF renders, bank portals, DigiLocker. <strong>Deliverable:</strong> Full local vision pipeline with privacy redaction working on real government portals.</div>\n      </div>\n      <div class=\"timeline-item\">\n        <div class=\"timeline-dot green\"></div>\n        <div class=\"timeline-phase\" style=\"color:var(--color-success)\">Phase 3 &mdash; Cloud Intelligence (Weeks 7&#x2013;9) &middot; Full Agentic Loop</div>\n        <div class=\"timeline-content\">Deploy svc-orchestrator (FastAPI + LangGraph), svc-vlm-cloud (Gemini adapter), svc-policy (OPA), svc-analytics. Implement WebSocket streaming for action plans. Build Agent Runner with DOM event dispatch + rollback stack. Build approval UI in Side Panel. <strong>Deliverable:</strong> Full end-to-end agent loop &mdash; describe a task, approve, watch it execute safely.</div>\n      </div>\n      <div class=\"timeline-item\">\n        <div class=\"timeline-dot purple\"></div>\n        <div class=\"timeline-phase\" style=\"color:var(--color-purple)\">Phase 4 &mdash; Polish &amp; Evaluation (Weeks 10&#x2013;12) &middot; Production Ready</div>\n        <div class=\"timeline-content\">Performance optimization (sub-200ms local pipeline). Security hardening (Snyk scan, CSP audit, cert pinning). Accessibility (ARIA labels, keyboard navigation). Grafana dashboard + monitoring. User study with ISRO evaluators. Chrome Web Store submission prep. Demo video production. <strong>Deliverable:</strong> Submission-ready product with full documentation and live demo.</div>\n      </div>\n    </div>",
  "s1_part1": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F3DB;&#xFE0F;</div>\n      <h2 class=\"section-title\">System Overview &mdash; The Big Picture</h2>\n    </div>\n    <p class=\"section-lead\">PRATYAKSHA is a <strong>hybrid local-cloud system</strong>. The most privacy-sensitive computation &mdash; screen capture, vision inference, and PII de-identification &mdash; is performed entirely inside the Chrome browser using WebGPU-accelerated ONNX models. Only a sanitized, token-substituted representation of the screen is sent to cloud services for high-level reasoning.</p>\n    <div class=\"callout orange\">\n      <div class=\"callout-icon\">&#x1F510;</div>\n      <div class=\"callout-body\"><div class=\"callout-title\">The Core Privacy Contract</div>Raw screenshots, biometric data (faces), and Aadhaar/PAN numbers are <strong>NEVER transmitted</strong> outside the browser extension. The Vault service pseudonymises all PII before anything crosses the local boundary. The cloud sees only tokens like <span class=\"mono\">&#x27E8;FACE_001&#x27E9;</span> and <span class=\"mono\">&#x27E8;AADHAAR_01&#x27E9;</span>.</div>\n    </div>\n        <!-- \u2500\u2500 MERMAID MASTER ARCHITECTURE FLOWCHART \u2500\u2500 -->",
  "s1_part2": "<div class=\"mermaid-legend\">\n        <div class=\"legend-item\"><span class=\"legend-dot ld-client\"></span><span>Client Presentation &amp; Runner</span></div>\n        <div class=\"legend-item\"><span class=\"legend-dot ld-shield\"></span><span>WebGPU Vision Privacy Shield</span></div>\n        <div class=\"legend-item\"><span class=\"legend-dot ld-vault\"></span><span>Zero-Knowledge Cryptographic Vault</span></div>\n        <div class=\"legend-item\"><span class=\"legend-dot ld-gateway\"></span><span>Edge Ingress &amp; Auth (DMZ)</span></div>\n        <div class=\"legend-item\"><span class=\"legend-dot ld-cloud\"></span><span>Sovereign Cloud Reasoning (vLLM)</span></div>\n        <div class=\"legend-item\"><span class=\"legend-dot ld-storage\"></span><span>Enterprise Storage &amp; Telemetry</span></div>\n        <div class=\"legend-item\"><span class=\"legend-dot ld-gate\"></span><span>Security &amp; Human Approval Gate</span></div>\n      </div>\n\n      <div class=\"mermaid-box\" id=\"mermaidBoxMain\">\n        <pre class=\"mermaid\" id=\"mermaidPreMain\">\nflowchart TD\n    %% Custom Semantic Styling Classes\n    classDef client fill:#EFF6FF,stroke:#2563EB,stroke-width:2px,color:#1E40AF;\n    classDef shield fill:#FFF7ED,stroke:#EA580C,stroke-width:2px,color:#9A3412;\n    classDef vault fill:#F5F3FF,stroke:#7C3AED,stroke-width:2px,color:#5B21B6;\n    classDef gateway fill:#FEF3C7,stroke:#D97706,stroke-width:2px,color:#92400E;\n    classDef cloud fill:#ECFDF5,stroke:#059669,stroke-width:2px,color:#065F46;\n    classDef storage fill:#F8FAFC,stroke:#475569,stroke-width:2px,color:#1E293B;\n    classDef gate fill:#FFF1F2,stroke:#E11D48,stroke-width:2px,stroke-dasharray: 4 4,color:#9F1239;\n\n    subgraph PHASE1 [\"\ud83d\udd12 STAGE 1: ON-DEVICE PERCEPTION & PRIVACY SHIELD (Client MV3 Sandbox)\"]\n        direction TB\n        User([\"\ud83d\udc64 User / Security Operator\"]):::client\n        SidePanel[\"\ud83d\udda5\ufe0f svc-ext-shell (Chrome Side Panel UI \u00b7 Audit HUD)\"]:::client\n        TargetTab[\"\ud83c\udf10 Target Web Portal (ISRO e-Procurement \u00b7 GeM \u00b7 SAKSHAM)\"]:::client\n        ContentExtractor[\"\ud83d\udcdc Content Script (DOM Scene Tree Extractor & Element Walker)\"]:::client\n        \n        subgraph WEBGPU_PIPELINE [\"\u26a1 svc-vision-local (Dedicated WebGPU Offscreen Context)\"]\n            TileDiff[\"\u26a1 8x8 Dirty-Tile dHash (Temporal Diff Filter \u00b7 Skips >85% Static Frames)\"]:::shield\n            NeuralDet[\"\ud83d\udd0d DBNet-Tiny + Ultra-Light-Face (Neural Text & Biometric Detectors)\"]:::shield\n            IndicOCR[\"\ud83d\udd24 Indic CRNN Engine (Devanagari, Tamil, Hindi, Latin OCR)\"]:::shield\n            PIIRules[\"\ud83c\uddee\ud83c\uddf3 Sovereign PII Validator (Verhoeff Checksum \u00b7 PAN \u00b7 GSTIN)\"]:::shield\n            Inpainter[\"\ud83c\udfa8 Safety Halo Inpainter (4px Dilated Redaction Canvas)\"]:::shield\n        end\n\n        VaultTokenize[(\"\ud83d\udd10 svc-vault-local: Tokenize<br/>(Maps Real PII \u2794 \u27e8SYNTHETIC_TOKENS\u27e9 in AES-256 Vault)\")]:::vault\n        MerkleChain[(\"\ud83d\udcdc Tamper-Proof Audit Chain (SHA-256 Merkle Ledger)\")]:::vault\n    end\n\n    subgraph PHASE2 [\"\ud83d\udeaa STAGE 2: ZERO-TRUST EDGE GATEWAY & EGRESS PERIMETER (DMZ)\"]\n        direction TB\n        EgressGuard{\"\ud83d\udee1\ufe0f Zero-Raw-PII Egress Guard<br/>(Hardware / Heuristic Packet Filter)\"}:::gate\n        APIGateway[\"\ud83d\udeaa svc-gateway<br/>(Envoy Ingress \u00b7 TLS 1.3 mTLS \u00b7 WSS Proxy)\"]:::gateway\n        AuthService[\"\ud83d\udd11 svc-auth<br/>(Device Attestation & Short-Lived JWT)\"]:::gateway\n    end\n\n    subgraph PHASE3 [\"\ud83e\udde0 STAGE 3: SOVEREIGN REASONING TIER (Air-Gapped Intranet)\"]\n        direction TB\n        Orchestrator[\"\ud83e\udde0 svc-orchestrator<br/>(FastAPI \u00b7 LangGraph State Machine Loop)\"]:::cloud\n        SovereignVLM[\"\ud83e\udd16 svc-vlm-cloud<br/>(Qwen2.5-VL-7B \u00b7 vLLM PagedAttention GPU)\"]:::cloud\n        PolicyEngine[\"\ud83d\udcdc svc-policy<br/>(Open Policy Agent \u00b7 Rego Guardrails)\"]:::cloud\n        \n        subgraph PERSISTENCE [\"\ud83d\udcbe Enterprise Telemetry & Persistence\"]\n            PostgresDB[(\"\ud83d\uddc4\ufe0f PostgreSQL (Session State & Trajectories)\")]:::storage\n            RedisCluster[(\"\u26a1 Redis Cluster (Locks & Token Cache)\")]:::storage\n            TimescaleDB[(\"\ud83d\udcca TimescaleDB (High-Throughput Telemetry)\")]:::storage\n            MinIOS3[(\"\ud83d\udce6 MinIO S3 (Sanitized Frames & Audit)\")]:::storage\n        end\n    end\n\n    subgraph PHASE4 [\"\ud83d\udd10 STAGE 4: LOCAL REHYDRATION & SAFE DOM EXECUTION (Service Worker & Tab)\"]\n        direction TB\n        AgentRunner[\"\ud83e\udd16 svc-agent-local<br/>(Action Downlink Receiver & State Machine)\"]:::client\n        HumanApprovalGate{\"\u26a0\ufe0f Level-3 Risk Gate<br/>(Mandatory User Confirmation Modal)\"}:::gate\n        VaultRehydrate[(\"\ud83d\udd10 svc-vault-local: Rehydrate<br/>(Swaps \u27e8TOKEN\u27e9 \u2794 Real PII in Local Volatile RAM)\")]:::vault\n        DOMDispatcher[\"\ud83d\udcdc Content Script (Synthetic Event Dispatcher)\"]:::client\n        MutatedTab[\"\ud83c\udf10 Target Web Portal (Mutated DOM State / Form Filled)\"]:::client\n    end\n\n    %% STAGE 1 FLOW\n    User -->|\"1. Submit Task Intent\"| SidePanel\n    SidePanel -->|\"2. Trigger Capture\"| ContentExtractor\n    ContentExtractor -->|\"3a. DOM Scene Tree\"| Inpainter\n    TargetTab -->|\"3b. Viewport Pixels (captureVisibleTab)\"| TileDiff\n    \n    TileDiff -->|\"4. Changed Tiles\"| NeuralDet\n    NeuralDet -->|\"5. BBoxes (Text & Faces)\"| IndicOCR\n    IndicOCR -->|\"6. Extracted Strings\"| PIIRules\n    PIIRules -->|\"7. Verified Coordinates\"| VaultTokenize\n    \n    VaultTokenize -->|\"8. Synthetic Tokens (\u27e8AADHAAR_01\u27e9)\"| Inpainter\n    Inpainter -->|\"9. Sanitized Canvas + Token Graph\"| MerkleChain\n    MerkleChain -->|\"10. Chained Hash Proof\"| EgressGuard\n\n    %% STAGE 2 FLOW\n    EgressGuard -->|\"11. Verified Zero-PII Egress\"| APIGateway\n    APIGateway <-->|\"12. Validate JWT & Device Attestation\"| AuthService\n    APIGateway -->|\"13. Forward Sanitized Request\"| Orchestrator\n\n    %% STAGE 3 FLOW\n    Orchestrator -->|\"14. Visual Reasoning Prompt (Tokens Only)\"| SovereignVLM\n    SovereignVLM -->|\"15. Candidate Action Hypothesis\"| PolicyEngine\n    PolicyEngine -->|\"16. Validated Action JSON\"| Orchestrator\n    \n    Orchestrator -.->|\"Session State\"| PostgresDB\n    Orchestrator -.->|\"Token Locks\"| RedisCluster\n    Orchestrator -.->|\"Real-Time Metrics\"| TimescaleDB\n    Orchestrator -.->|\"Sanitized Frame Audit\"| MinIOS3\n\n    %% STAGE 4 FLOW (Linear forward transition)\n    Orchestrator ==>|\"17. WSS Action Plan Downlink\"| AgentRunner\n    AgentRunner -->|\"18. Evaluate Action Severity\"| HumanApprovalGate\n    HumanApprovalGate -->|\"L3 Mutation: Prompt User\"| SidePanel\n    SidePanel -->|\"User Approves\"| AgentRunner\n    HumanApprovalGate -->|\"L1/L2 Safe: Auto-Proceed\"| VaultRehydrate\n    \n    AgentRunner -->|\"19. Resolve Token \u27e8AADHAAR_01\u27e9\"| VaultRehydrate\n    VaultRehydrate -->|\"20. Decrypted String (In-Memory Only)\"| AgentRunner\n    AgentRunner -->|\"21. Dispatch Synthetic Event (Click / Type)\"| DOMDispatcher\n    DOMDispatcher -->|\"22. Apply Mutation to Active DOM\"| MutatedTab\n    MutatedTab -.->|\"23. Next Frame Closed-Loop Perception\"| TargetTab\n        </pre>\n        <div class=\"mermaid-canvas-hint\">\n          <span>\ud83d\udd90\ufe0f Drag to Pan</span>\n          <span>\u00b7</span>\n          <span>\ud83d\udd0d Pinch or Scroll to Zoom</span>\n        </div>\n      </div>\n\n      <div class=\"matrix-table-wrap\">\n        <table class=\"api-table\">\n          <thead>\n            <tr>\n              <th>Service Codename</th>\n              <th>Deployment Zone</th>\n              <th>Runtime &amp; Protocol</th>\n              <th>Upstream / Downstream Relationships</th>\n              <th>Security &amp; Data Contract</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td><code>svc-ext-shell</code></td>\n              <td>Chrome MV3 Extension</td>\n              <td>Side Panel UI \u00b7 Chrome Runtime WSS</td>\n              <td>User &rarr; <code>svc-agent-local</code>, <code>Content Script</code></td>\n              <td>Zero network egress authority; user intent input &amp; audit diff UI only.</td>\n            </tr>\n            <tr>\n              <td><code>svc-vision-local</code></td>\n              <td>Offscreen Document</td>\n              <td>WebGPU \u00b7 ONNX Runtime Web</td>\n              <td>Tab Canvas &rarr; <code>svc-vault-local</code>, <code>svc-ledger-local</code></td>\n              <td>Local GPU acceleration; destroys raw pixel buffer immediately after sanitization.</td>\n            </tr>\n            <tr>\n              <td><code>svc-vault-local</code></td>\n              <td>Service Worker</td>\n              <td>IndexedDB (AES-256-GCM)</td>\n              <td><code>svc-vision-local</code> &harr; <code>svc-agent-local</code></td>\n              <td>Single source of truth for PII tokens; keys never leave client device memory.</td>\n            </tr>\n            <tr>\n              <td><code>svc-agent-local</code></td>\n              <td>Service Worker</td>\n              <td>TypeScript Event Loop</td>\n              <td><code>svc-orchestrator</code> &rarr; <code>Content Script</code></td>\n              <td>Executes action plans; prompts user on high-severity mutations (payment, delete).</td>\n            </tr>\n            <tr>\n              <td><code>svc-gateway</code></td>\n              <td>Edge Ingress (Envoy)</td>\n              <td>TLS 1.3 \u00b7 Mutual Auth \u00b7 WSS/HTTPS</td>\n              <td>Client Extension &rarr; <code>svc-orchestrator</code></td>\n              <td>Rejects any incoming payload failing heuristic Indian PII checks.</td>\n            </tr>\n            <tr>\n              <td><code>svc-orchestrator</code></td>\n              <td>Private Kubernetes Cluster</td>\n              <td>FastAPI + LangGraph \u00b7 Python 3.11</td>\n              <td><code>svc-gateway</code> &harr; <code>svc-vlm-cloud</code>, <code>svc-policy</code></td>\n              <td>Multi-step goal decomposition; handles workflow state transitions.</td>\n            </tr>\n            <tr>\n              <td><code>svc-vlm-cloud</code></td>\n              <td>Air-Gapped Intranet GPU</td>\n              <td>vLLM \u00b7 Qwen2.5-VL-7B-Instruct</td>\n              <td><code>svc-orchestrator</code></td>\n              <td>Pure vision reasoning over sanitized scene; emits token-targeted action hypotheses.</td>\n            </tr>\n            <tr>\n              <td><code>svc-policy</code></td>\n              <td>Private Kubernetes Cluster</td>\n              <td>Open Policy Agent (OPA) \u00b7 Rego</td>\n              <td><code>svc-orchestrator</code></td>\n              <td>Enforces URL allowlists, rate limiting, and destructive action blocks.</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n    <div class=\"highlight-row\">\n      <div class=\"hl-card\"><span class=\"hl-icon\">&#x1F9E9;</span><div class=\"hl-title\">8 Microservices</div><div class=\"hl-body\">Each service is independently deployable, versioned, and has a single responsibility. Local services run inside the Chrome extension Manifest V3 service worker and offscreen document.</div></div>\n      <div class=\"hl-card\"><span class=\"hl-icon\">&#x1F510;</span><div class=\"hl-title\">Zero-Trust Boundary</div><div class=\"hl-body\">The local-to-cloud boundary enforces a strict \"sanitize-before-transmit\" contract. The Vault holds the only copy of the PII &#x2194; token mapping, never replicated to cloud.</div></div>\n      <div class=\"hl-card\"><span class=\"hl-icon\">&#x26A1;</span><div class=\"hl-title\">WebGPU Acceleration</div><div class=\"hl-body\">On-device vision models run entirely in WebGPU via ONNX Runtime Web, achieving ~120 ms inference on mid-range hardware with no GPU driver install needed.</div></div>\n    </div>",
  "s3_part1": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F30A;</div>\n      <h2 class=\"section-title\">7-Step Data-Flow Architecture</h2>\n    </div>\n    <p class=\"section-lead\">Every PRATYAKSHA request follows a strict 7-step pipeline. Steps 1&#x2013;3 are executed locally; steps 4&#x2013;5 happen in the cloud (with only sanitized data); steps 6&#x2013;7 rehydrate tokens back to real values locally before the agent acts.</p>\n        <!-- \u2500\u2500 MERMAID 7-STEP CHRONOLOGICAL SEQUENCE \u2500\u2500 -->",
  "s3_part2": "<div class=\"mermaid-box\" id=\"mermaidBoxSeq\">\n        <pre class=\"mermaid\" id=\"mermaidPreSeq\">\nsequenceDiagram\n    autonumber\n    actor User as \ud83d\udc64 User / Operator\n    participant Tab as \ud83c\udf10 Target Tab DOM\n    participant Content as \ud83d\udcdc Content Script\n    participant Offscreen as \u26a1 WebGPU Privacy Shield\n    participant Vault as \ud83d\udd10 Local Vault Service\n    participant Gateway as \ud83d\udeaa API Gateway\n    participant Orchestrator as \ud83e\udde0 Orchestrator (LangGraph)\n    participant VLM as \ud83e\udd16 Sovereign VLM (vLLM)\n\n    User->>Content: 1. Submit task intent via Side Panel (\"Fill supplier bid\")\n    Content->>Tab: 2. Traverse interactive elements & computed styles\n    Tab-->>Content: 3. Return structured DOM scene tree\n    Content->>Offscreen: 4. chrome.tabs.captureVisibleTab() + DOM scene tree\n    Note over Offscreen: Stage A: 8x8 dHash skips redundant static tiles<br/>Stage B: DBNet detects text regions in PDFs/Canvases<br/>Stage C: Ultra-Light-Face flags biometrics<br/>Stage D: CRNN OCR extracts Devanagari + Latin strings<br/>Stage E: Verhoeff algorithm validates 12-digit Aadhaar\n    Offscreen->>Vault: 5. Register verified PII {type: 'AADHAAR', raw: '5489-1234-8901', bbox}\n    Vault-->>Offscreen: 6. Return typed token \u27e8AADHAAR_01\u27e9\n    Note over Offscreen: Stage F: 4px safety halo dilation inpainting on canvas<br/>Stage G: SHA-256 Merkle egress hash proof generated\n    Offscreen->>Gateway: 7. POST /v1/agent/task (Sanitized canvas + Tokenized scene + Hash proof)\n    Note over Gateway: Ingress inspection: Verify TLS 1.3 + JWT<br/>Heuristic check: Zero raw PII allowed across boundary\n    Gateway->>Orchestrator: 8. Forward sanitized task context\n    Orchestrator->>VLM: 9. Prompt Qwen2.5-VL with sanitized image & token IDs\n    Note over VLM: Model inspects layout & synthetic tokens<br/>Plans next step: Click input box \u27e8AADHAAR_01\u27e9\n    VLM-->>Orchestrator: 10. Emits structured action plan JSON\n    Orchestrator-->>Content: 11. Stream Action Plan frame via WebSocket\n    Note over Content: Intercept action targeting \u27e8AADHAAR_01\u27e9\n    Content->>Vault: 12. Query real decrypted value for token \u27e8AADHAAR_01\u27e9\n    Vault-->>Content: 13. Return real Aadhaar string (in local RAM only)\n    Content->>Tab: 14. dispatchEvent(new InputEvent('input', {data: realValue}))\n    Tab-->>User: 15. Real-time visual confirmation in portal\n        </pre>\n        <div class=\"mermaid-canvas-hint\">\n          <span>\ud83d\udd90\ufe0f Drag to Pan</span>\n          <span>\u00b7</span>\n          <span>\ud83d\udd0d Pinch or Scroll to Zoom</span>\n        </div>\n      </div>\n    </div>\n    </div>\n    <div class=\"card\"><div class=\"card-title\">&#x1F4F8; Step 1 &mdash; PERCEIVE: Dual-Channel Screen Understanding</div><div class=\"card-body\"><strong>Channel A &mdash; DOM Extraction:</strong> The content script enumerates all interactive and semantic DOM nodes (inputs, buttons, headings, paragraphs, tables), extracting text content, ARIA labels, bounding boxes, and computed styles to produce a structured node tree.<br/><br/><strong>Channel B &mdash; Pixel Capture:</strong> <span class=\"mono\">chrome.tabs.captureVisibleTab()</span> captures the current viewport as a high-resolution PNG. This is passed directly to the Vision Worker &mdash; it <strong>NEVER</strong> leaves the local context before sanitization.<br/><br/><strong>Non-DOM Content (Key Innovation):</strong> PDFs rendered by the browser, embedded iframes, canvas elements, and SVG infographics cannot be read by DOM extraction alone. The Vision Worker's pixel pipeline handles these via the OCR + detection stack &mdash; this is the core problem this PS solves.</div></div>\n    <div class=\"card\"><div class=\"card-title\">&#x1F441;&#xFE0F; Step 2 &mdash; DETECT: Vision Worker Model Pipeline</div><div class=\"card-body\">The Vision Worker runs 4 models in sequence, each taking ~30 ms on WebGPU (total ~120 ms):<br/><br/><strong>&#x2460; Face Detector</strong> &mdash; YOLOv8-nano INT8: Detects all faces, produces bounding boxes. All detected faces are registered as <span class=\"mono\">&#x27E8;FACE_N&#x27E9;</span> tokens in the Vault.<br/><strong>&#x2461; Text Region Detector</strong> &mdash; DBNet-small: Detects all text regions including regions inside images/PDFs that DOM can't reach.<br/><strong>&#x2462; Indic OCR</strong> &mdash; CRNN with Devanagari + Latin: Reads text from detected regions. Pattern-matches against PII regexes (Aadhaar: 12-digit, PAN: AAAAA-9999-A, phone numbers, bank accounts).<br/><strong>&#x2463; Content Classifier</strong> &mdash; MobileNetV4-tiny: Classifies screen context (BANKING, MEDICAL, GOVERNMENT, GENERAL) to apply appropriate sanitization policy level.</div></div>\n    <div class=\"card\"><div class=\"card-title\">&#x1F512; Step 3 &mdash; SANITIZE: The Vault Service in Action</div><div class=\"card-body\"><strong>A. Image Redaction:</strong> Draws solid-colour fills (distinct per category: orange for faces, blue for Aadhaar, red for financial) over each detected PII bounding box on the captured canvas. The redacted canvas is what gets transmitted.<br/><br/><strong>B. Token Registry:</strong> For each detected PII item, generates a deterministic session-scoped token (e.g., <span class=\"mono\">&#x27E8;AADHAAR_01&#x27E9;</span>). Stores <span class=\"mono\">token &#x2192; {realValue, boundingBox, type, confidence}</span> in AES-256-GCM encrypted IndexedDB. Replaces real values in the scene graph JSON with their tokens.<br/><br/><strong>Output:</strong> A sanitized canvas (PNG) + a tokenized scene graph (JSON). These are the <em>only</em> artefacts that cross the local boundary.</div></div>\n    <div class=\"card\"><div class=\"card-title\">&#x1F9E0; Steps 4&#x2013;5 &mdash; REASON + PLAN: Cloud Intelligence Loop</div><div class=\"card-body\">The sanitized canvas + tokenized scene graph are sent to the Cloud VLM Reasoner via HTTPS POST through the API Gateway. The VLM returns structured understanding (layout, semantics, actionable elements &mdash; all referencing tokens, not real data). The Agent Orchestrator runs a LangGraph planning loop to produce a JSON Action Plan: a sequence of typed actions &mdash; <span class=\"mono\">CLICK(selector)</span>, <span class=\"mono\">TYPE(token_or_literal)</span>, <span class=\"mono\">SCROLL(delta)</span>, <span class=\"mono\">WAIT(ms)</span>, <span class=\"mono\">ASSERT(condition)</span>. The Policy Engine intercepts the plan before it is returned, checking each action against OPA rules.</div></div>\n    <div class=\"card\"><div class=\"card-title\">&#x1F504; Steps 6&#x2013;7 &mdash; REHYDRATE + EXECUTE: Local Action</div><div class=\"card-body\">The Action Plan arrives at the local Agent Runner still using tokens. The Vault Service is queried for each token to substitute the real value back &mdash; this happens entirely locally. The cloud never learns the real values. If a token is not found (tampered plan or hallucinated token), the action is blocked and the user is alerted. Rehydrated actions are then dispatched as real DOM events: <span class=\"mono\">dispatchEvent(new MouseEvent('click', ...))</span>, <span class=\"mono\">dispatchEvent(new InputEvent('input', ...))</span>, with each step logged to the local audit ledger and optionally synced (token-based) to the cloud ledger.</div></div>"
};
